column2:
如果创建的是可执行文件，必须在 main 函数开头调用 InitCVIRTE，如下所示。

    #include <cvirte.h>

    int main (int argc, char *argv[])
    {
        if (InitCVIRTE (0, argv, 0) == 0)
            return -1;       /* 内存不足 */
        /* 其他代码 */
        return 0;
    }

如果使用 WinMain()，代码应如下所示。

    #include <cvirte.h>

    int __stdcall WinMain (HINSTANCE hInstance,
                           HINSTANCE hPrevInstance,
                           LPSTR lpszCmdLine,
                           int nCmdShow)
    {
        if (InitCVIRTE (hInstance, 0, 0) == 0)
            return -1;       /* 内存不足 */
        /* 其他代码 */
        return 0;
    }

如果创建的是 DLL，必须在 DllMain 函数中调用 InitCVIRTE 与 CloseCVIRTE，如下所示。

    #include <cvirte.h>

    int __stdcall DllMain (void *hinstDLL, int fdwReason,
                           void *lpvReserved)
    {
        if (fdwReason == DLL_PROCESS_ATTACH)

        {
        if (InitCVIRTE (hinstDLL, 0, 0) == 0)
            return 0;     /* 内存不足 */
        /* 其他 ATTACH 代码 */
        }
    else if (fdwReason == DLL_PROCESS_DETACH)
        {
        /* 其他 DETACH 代码 */
        CloseCVIRTE ();
        }

return 1;
}
